inline std::optional<flight::String> get_wgpu_compressed_texture_format(flight::host_sdl::WgpuDevice device, flight::types::TextureContainerFormat format) {
  auto info = get_compressed_format_info(format);
  if (!info.has_value()) {
    return std::nullopt;
  }
  auto support = detect_wgpu_compressed_texture_support(device);
  if (format.starts_with(flight::String("bc"))) {
    return (support->bc ? std::optional<flight::String>{info.value()->format} : std::nullopt);
  }
  if (format.starts_with(flight::String("astc"))) {
    return (support->astc ? std::optional<flight::String>{info.value()->format} : std::nullopt);
  }
  return (support->etc2 ? std::optional<flight::String>{info.value()->format} : std::nullopt);
}

inline bool has_wgpu_compressed_texture_format(flight::StructuralRef<flight::RowReadonly<flight::RowOf<flight::Ref<flight::types::WgpuCompressedTextureSupport>>>> support, flight::types::TextureContainerFormat format) {
  if (!get_compressed_format_info(format).has_value()) {
    return false;
  }
  if (format.starts_with(flight::String("bc"))) {
    return flight::row_get<flight::RowKey<"bc">>(support);
  }
  if (format.starts_with(flight::String("astc"))) {
    return flight::row_get<flight::RowKey<"astc">>(support);
  }
  return flight::row_get<flight::RowKey<"etc2">>(support);
}

